        const del = document.createElement('button')
        del.type = 'button'
        del.className = 'btn'
        del.textContent = 'Löschen'
        del.setAttribute('aria-label', `${u.name}: Löschen`)
        del.disabled = u.id === r.body.current || r.body.users.length < 2
        del.onclick = () => remove(u, r.body)
